// payslipTemplate.js
//
// THE payslip. One template, rendered identically by the employee app (all
// three platforms) and by the HR dashboard in the CMS.
//
// ─────────────────────────────────────────────────────────────────────────────
//  THIS FILE IS DUPLICATED, ON PURPOSE, AND MUST STAY BYTE-IDENTICAL:
//
//      App/src/lib/payslipTemplate.js
//      grav-cms/lib/payslipTemplate.js
//
//  The two repos share no package, so nothing enforces this automatically.
//  Change one, change the other, and check they still match:
//
//      sha256sum App/src/lib/payslipTemplate.js grav-cms/lib/payslipTemplate.js
//
//  Before this file existed the payslip was written twice — a template string
//  in the app's SalaryScreen and JSX in the CMS's payslip page — and the two
//  had already drifted: the app hard-coded a logo URL and printed a purple
//  tagline the CMS took from the API. Same document, two different pieces of
//  paper depending on who generated it.
// ─────────────────────────────────────────────────────────────────────────────
//
// ── Where the design comes from ─────────────────────────────────────────────
// payslip_template_montserrat.docx, transcribed field by field:
//
//   font          Montserrat throughout (docDefaults rFonts)
//   company name  16pt bold #595959      subtitle  12pt bold #808080
//   labels        bold #808080 on #F2F2F2   values  bold #1A1A1A on #FFFFFF
//   footer        9pt bold #A6A6A6
//   borders       0.5pt solid black (w:sz="4" = eighths of a point)
//   rows          minimum height 420 twips = 21pt, contents vertically centred
//   column widths taken from each w:tblGrid and converted to percentages of
//                 the 10800-twip (7.5in) text column:
//                   header   1440 / 7920 / 1440         13.333 / 73.333 / 13.333
//                   info     2700 x 4                    25 each
//                   summary  3600 x 3                    33.333 each
//                   earn/ded 3240 / 2160 / 3240 / 2160   30 / 20 / 30 / 20
//                   employer 7559 / 3240                 70 / 30
//
// Two deliberate departures from the .docx, both noted where they occur:
//   · A4, not US Letter. The .docx is Letter because that is Word's default on
//     the machine it was made on; every printer this lands on is A4, and the
//     CMS print stylesheet already says A4. Column widths are percentages, so
//     the layout is identical either way. PAGE_SIZE below flips it.
//   · Cell padding. The .docx sets tblCellMar to 0, which renders text flush
//     against the rule. Reproduced literally that is hard to read, so cells get
//     8px of horizontal padding; the 21pt row height and vertical centring —
//     which are what the eye actually reads as the table's rhythm — are exact.

// The mark, inlined as a data URI rather than fetched.
//
// It used to be an https:// URL. The URL resolves — that is not the problem.
// The problem is WHEN: printHtmlToPdf hands the document to expo-print (or to
// a hidden iframe on web) and prints it almost immediately, and a remote image
// that has not finished loading by then is simply absent from the PDF. It
// races, so it works on a fast connection and silently drops the logo on a
// slow one, which is the worst way for it to fail. Inlined, there is nothing
// to wait for and nothing to be offline for.
//
// This is the exact logo.png embedded in payslip_template_montserrat.docx,
// 592x446, ~13KB.
const LOGO_DATA_URI =
  "data:image/png;base64,";

// The masthead is DESIGN, not data — same argument as the logo above.
//
// It used to come from the API's company.name, and the two endpoints that
// serve this document disagree: /api/hr/payslip returns "Grav Clothing ( OPC )
// Pvt Ltd" and /api/employee/payslip returns "Grav Clothing". So the CMS and
// the app printed different company names on the same payslip, from the same
// template, and no amount of matching the CSS would ever have fixed it.
//
// This is the string exactly as payslip_template_montserrat.docx sets it,
// spaces around (OPC) included. opts.companyName overrides it if a second
// legal entity ever needs its own paper.
const COMPANY_NAME = "Grav Clothing ( OPC ) Pvt Ltd";

// A4. Set to "letter" to match the source .docx exactly.
const PAGE_SIZE = "A4";

// 0.5in margins, as w:pgMar in the source (720 twips on every side).
//
// Applied as PADDING on the slip, with @page set to margin:0 — not the other
// way round. Chrome only draws its own print header and footer (the date, the
// document title, the page URL, the page number) when the @page margin leaves
// room for them; at margin:0 it has nowhere to put them and omits them. That
// is the only way to get rid of "8/24/26, 10:21 AM" and "localhost:8081/pay"
// off a printed payslip from inside the document, because they are the
// browser's chrome and not ours to delete.
//
// The CMS print stylesheet already did exactly this. The app document did not,
// which is why the two produced different paper from the same template.
const PAGE_MARGIN = "12.7mm";

// Three cell kinds, and the .docx is precise about which goes where:
//   gp-lbl  #F2F2F2 fill, #808080 ink — info labels, column headers, totals
//   gp-row  #F2F2F2 fill, #1A1A1A ink — earnings/deduction LINE ITEMS
//   gp-val  #FFFFFF fill, #1A1A1A ink — every figure
// Collapsing the first two is the obvious simplification and it is wrong:
// it greys out "Basic Salary" and "Provident Fund", which the source sets in
// full-strength ink precisely so the line items read louder than the headings
// above them.
const INK = {
  title: "#595959",
  subtitle: "#808080",
  label: "#808080",
  value: "#1A1A1A",
  footer: "#A6A6A6",
  labelFill: "#F2F2F2",
  valueFill: "#FFFFFF",
  rule: "#000000",
};

/** Escape a value for interpolation into HTML. */
function esc(v) {
  if (v === null || v === undefined) return "";
  return String(v)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

/** Indian-format money, two decimals, no symbol — the .docx shows bare numbers. */
function fmtINR(n) {
  return Number(n || 0).toLocaleString("en-IN", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  });
}

/**
 * The stylesheet. Exported so the CMS can inject exactly these rules next to
 * the same markup, rather than reimplementing them in JSX and drifting.
 *
 * Every selector is namespaced under .gp- so dropping this into the dashboard
 * cannot collide with Tailwind or the app shell.
 */
export const PAYSLIP_CSS = `
/* Montserrat 700, latin subset, embedded.
 *
 * It was an @import from fonts.googleapis.com. Two problems with that on a
 * document like this. First, correctness: every renderer here prints almost
 * immediately, so a font still in flight means the PDF is quietly typeset in
 * the fallback — and on a server with restricted egress, or a phone offline,
 * that is not a race, it is the guaranteed outcome. Second, cost: the server
 * renderer paid a network round trip on EVERY payslip.
 *
 * Only weight 700 is embedded because every glyph in this document is bold —
 * labels, figures, masthead, footnote. Anything else falls back to the stack
 * below, which is the correct behaviour rather than an oversight.
 *
 * 18.8KB of woff2, and it makes the document faster, not slower. Measured on
 * the server renderer: 2238ms per payslip with the @import, 329ms with the
 * font embedded. The PDF is smaller too — 49KB down to 47KB — because
 * Chromium subsets what it actually used rather than the whole webfont.
 */
@font-face {
  font-family: 'Montserrat';
  font-style: normal;
  font-weight: 700;
  font-display: block;
  src: url(data:font/woff2;base64,) format('woff2');
}

.gp-slip {
  background: #fff;
  color: ${INK.value};
  /* The page margin lives HERE, not in @page. See PAGE_MARGIN. */
  padding: ${PAGE_MARGIN};
  font-family: Montserrat, 'Segoe UI', Helvetica, Arial, sans-serif;
  font-size: 10pt;
  line-height: 1.3;
  box-sizing: border-box;
  -webkit-print-color-adjust: exact;
  print-color-adjust: exact;
}
.gp-slip * { box-sizing: border-box; }

.gp-slip table {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
  margin: 0 0 10px;
}
.gp-slip td, .gp-slip th {
  border: 0.5pt solid ${INK.rule};
  height: 21pt;
  padding: 2px 8px;
  vertical-align: middle;
  text-align: left;
  font-weight: 700;
  font-size: 10pt;
  word-break: break-word;
}
/* Every modifier is qualified with .gp-slip on purpose. The base rule for
   cells is ".gp-slip td", specificity (0,1,1); a bare ".gp-num" is (0,1,0)
   and loses to it, so every amount silently left-aligns. The masthead's
   centring went the same way. */
.gp-slip .gp-lbl { background: ${INK.labelFill}; color: ${INK.label}; }
.gp-slip .gp-row { background: ${INK.labelFill}; color: ${INK.value}; }
.gp-slip .gp-val { background: ${INK.valueFill}; color: ${INK.value}; }
.gp-slip .gp-num { text-align: right; font-variant-numeric: tabular-nums; }

/* The masthead is a borderless three-column table in the source, with the
   logo pinned left and the wordmark optically centred in the page — not
   centred in the space left over beside the logo. The empty right cell is
   what buys that, so it is kept rather than "simplified" away. */
.gp-head, .gp-head td { border: 0; height: auto; padding: 0; background: none; }
.gp-head { margin-bottom: 14px; }
.gp-logo { width: 13.333%; }
.gp-logo img { max-width: 100%; max-height: 78px; object-fit: contain; display: block; }
.gp-slip .gp-mast { width: 73.333%; text-align: center; }
.gp-spacer { width: 13.333%; }
.gp-co {
  font-size: 16pt; font-weight: 700; color: ${INK.title};
  margin: 0; letter-spacing: 0.2px; line-height: 1.2;
}
.gp-period {
  font-size: 12pt; font-weight: 700; color: ${INK.subtitle};
  margin: 2px 0 0; line-height: 1.2;
}
.gp-note {
  font-size: 9pt; font-weight: 700; color: ${INK.footer};
  margin: 18px 0 0;
}
`;

/** True for null, undefined, "", "   ", and the string "null"/"undefined". */
function blank(v) {
  if (v === null || v === undefined) return true;
  const t = String(v).trim();
  return t === "" || t === "null" || t === "undefined";
}

/**
 * The employee block, built from the fields this employee ACTUALLY has.
 *
 * Not every worker is enrolled in provident fund or ESI. Printing "PF No",
 * "UAN No" and "ESI No" as three empty boxes on their payslip states a
 * relationship with the EPFO and the ESIC that does not exist, and it invites
 * the reading that the number is missing rather than inapplicable — which,
 * on a pay document, is the kind of thing people come to HR about.
 *
 * So: take the pairs that have a value, then re-flow them two-up. Dropping a
 * pair mid-grid is why this cannot be a fixed list of rows — remove "PF No"
 * from a hard-coded 4-column layout and "Emp No" is left sitting beside a
 * hole. Re-flowing closes the gap and "UAN No" moves up into it.
 *
 * A field that is genuinely unknown rather than inapplicable still shows,
 * blank, because these are all fields every employee has: name, department,
 * bank. Only the statutory identifiers come and go.
 */
function infoBlock(fields) {
  const present = fields.filter((f) => f.always || !blank(f.value));
  let out = "";
  for (let i = 0; i < present.length; i += 2) {
    const a = present[i];
    const b = present[i + 1];
    out +=
      `<tr>` +
      `<td class="gp-lbl">${esc(a.label)}</td>` +
      `<td class="gp-val">${esc(a.value)}</td>` +
      // An odd number of fields leaves one trailing pair of cells. They are
      // drawn empty rather than colspan-ed so the column rules stay unbroken
      // down the whole table, which is how the .docx renders.
      `<td class="gp-lbl">${b ? esc(b.label) : ""}</td>` +
      `<td class="gp-val">${b ? esc(b.value) : ""}</td>` +
      `</tr>`;
  }
  return out;
}

/**
 * The payslip itself, as an HTML fragment — one <div class="gp-slip">.
 *
 * Kept separate from renderPayslipHtml so the CMS can put the SAME markup
 * straight into its printable container and show on screen exactly what comes
 * out of the printer, while the app wraps it in a document for expo-print.
 *
 * @param {object} data              the /payslip response payload
 * @param {object} [opts]
 * @param {string} [opts.companyName] override the masthead. Both repos leave
 *                                   this unset, which is the point.
 * @param {string} [opts.logoUrl]    override the embedded mark. Rarely wanted:
 *                                   a remote image races the print call and
 *                                   can be missing from the PDF. Both repos
 *                                   leave it unset, so both print the same
 *                                   logo with no network involved.
 */
export function renderPayslipBody(data, opts = {}) {
  if (!data) return "";
  const {
    period = {},
    employee = {},
    attendance = {},
    summary = {},
    earnings = [],
    deductions = [],
    employerContributions = {},
  } = data;

  // The embedded mark is the DEFAULT, and company.logoUrl is deliberately not
  // consulted. Any http(s) logo — including one the API supplies — is a
  // network fetch racing the print call, and losing that race means a payslip
  // with no logo on it. A caller that genuinely wants a remote image can still
  // pass opts.logoUrl and accept the trade.
  const logo = opts.logoUrl || LOGO_DATA_URI;

  // Earnings and deductions run side by side, so the block is as tall as the
  // longer of the two and the shorter one pads with empty cells. The source
  // .docx shows three earnings against one deduction doing exactly this.
  const rows = Math.max(earnings.length, deductions.length, 1);
  let edRows = "";
  for (let i = 0; i < rows; i++) {
    const e = earnings[i];
    const d = deductions[i];
    edRows +=
      `<tr>` +
      `<td class="gp-row">${esc(e ? e.label : "")}</td>` +
      `<td class="gp-val gp-num">${e ? fmtINR(e.amount) : ""}</td>` +
      `<td class="gp-row">${esc(d ? d.label : "")}</td>` +
      `<td class="gp-val gp-num">${d ? fmtINR(d.amount) : ""}</td>` +
      `</tr>`;
  }

  // Employer contributions sit in their own 70/30 table with no header row —
  // the source shows a bare "Employer PF Contribution" line. ESIC is kept
  // alongside it, in the same shape: the .docx has no row for it, but the
  // payroll API returns it and dropping a figure an employee is entitled to
  // see would be losing data to match a layout.
  let employerRows = "";
  if (Number(employerContributions.epf) > 0) {
    employerRows +=
      `<tr><td class="gp-row">Employer PF Contribution</td>` +
      `<td class="gp-val gp-num">${fmtINR(employerContributions.epf)}</td></tr>`;
  }
  if (Number(employerContributions.esic) > 0) {
    employerRows +=
      `<tr><td class="gp-row">Employer ESIC Contribution</td>` +
      `<td class="gp-val gp-num">${fmtINR(employerContributions.esic)}</td></tr>`;
  }
  const employerTable = employerRows
    ? `<table><colgroup><col style="width:70%"><col style="width:30%"></colgroup>` +
      `<tbody>${employerRows}</tbody></table>`
    : "";

  const worked =
    `${attendance.payableDays || 0} / ${attendance.workingDays || 0}`;

  // `always` marks a field every employee has, so it prints even when the
  // value is missing — an unknown bank name is a gap in the record, whereas a
  // missing PF number usually means there is no PF. Order is the .docx's,
  // reading down the left column then the right.
  const infoFields = infoBlock([
    { label: "Name", value: employee.name, always: true },
    { label: "PAN No", value: employee.panNo },
    { label: "Emp No", value: employee.empNo, always: true },
    { label: "PF No", value: employee.pfNo },
    { label: "Pay Period", value: employee.payPeriod, always: true },
    { label: "UAN No", value: employee.uanNo },
    { label: "DOJ", value: employee.doj, always: true },
    { label: "ESI No", value: employee.esiNo },
    { label: "DOB", value: employee.dob, always: true },
    { label: "Department", value: employee.department, always: true },
    { label: "Bank Name", value: employee.bankName, always: true },
    { label: "Designation", value: employee.designation, always: true },
    { label: "Bank A/C No", value: employee.bankAccountNo, always: true },
    { label: "Total Worked Days", value: worked, always: true },
  ]);

  return `<div class="gp-slip">

  <table class="gp-head">
    <colgroup><col class="gp-logo"><col class="gp-mast"><col class="gp-spacer"></colgroup>
    <tbody><tr>
      <td class="gp-logo">${
        logo ? `<img src="${esc(logo)}" alt="">` : ""
      }</td>
      <td class="gp-mast">
        <p class="gp-co">${esc(opts.companyName || COMPANY_NAME)}</p>
        <p class="gp-period">Payslip for the Month ${esc(period.label || "")}</p>
      </td>
      <td class="gp-spacer"></td>
    </tr></tbody>
  </table>

  <table>
    <colgroup><col style="width:25%"><col style="width:25%"><col style="width:25%"><col style="width:25%"></colgroup>
    <tbody>
      ${infoFields}
    </tbody>
  </table>

  <table>
    <colgroup><col style="width:33.333%"><col style="width:33.333%"><col style="width:33.334%"></colgroup>
    <tbody>
      <tr>
        <td class="gp-lbl">Gross Earnings</td>
        <td class="gp-lbl">Deduction</td>
        <td class="gp-lbl">Net Pay</td>
      </tr>
      <tr>
        <td class="gp-val gp-num">${fmtINR(summary.grossEarnings)}</td>
        <td class="gp-val gp-num">${fmtINR(summary.totalDeduction)}</td>
        <td class="gp-val gp-num">${fmtINR(summary.netPay)}</td>
      </tr>
    </tbody>
  </table>

  <table>
    <colgroup><col style="width:30%"><col style="width:20%"><col style="width:30%"><col style="width:20%"></colgroup>
    <tbody>
      <tr>
        <td class="gp-lbl">Earnings</td>
        <td class="gp-lbl gp-num">Amount</td>
        <td class="gp-lbl">Deductions</td>
        <td class="gp-lbl gp-num">Amount</td>
      </tr>
      ${edRows}
      <tr>
        <td class="gp-lbl">Total Earnings</td>
        <td class="gp-val gp-num">${fmtINR(summary.grossEarnings)}</td>
        <td class="gp-lbl">Total Deduction</td>
        <td class="gp-val gp-num">${fmtINR(summary.totalDeduction)}</td>
      </tr>
      <tr>
        <td class="gp-row"></td>
        <td class="gp-val"></td>
        <td class="gp-lbl">Take Home Pay</td>
        <td class="gp-val gp-num">${fmtINR(
          summary.takeHomePay != null ? summary.takeHomePay : summary.netPay,
        )}</td>
      </tr>
    </tbody>
  </table>

  ${employerTable}

  <p class="gp-note">This Payslip is computer generated and does not require any signature</p>
</div>`;
}

/**
 * The same payslip as a complete, standalone HTML document.
 *
 * This is what goes to expo-print on Android and iOS, and to the browser's
 * print pipeline on web — see lib/document.js. The @page rule is here rather
 * than in PAYSLIP_CSS because the CMS renders the fragment inside a dashboard
 * that has its own page rules.
 */
export function renderPayslipHtml(data, opts = {}) {
  return `<!DOCTYPE html>
<html><head><meta charset="utf-8">
<title>Payslip</title>
<style>
${PAYSLIP_CSS}
@page { size: ${PAGE_SIZE}; margin: 0; }
html, body { margin: 0; padding: 0; background: #fff; }
</style>
</head><body>${renderPayslipBody(data, opts)}</body></html>`;
}

export default renderPayslipHtml;
